const Items = items.map(i => i.json);
const jsonData = Items[0];

const actuators = jsonData.actuators;

let entitiesToUpdate = [];

// Converts HH:MM or HH:MM:SS to full datetime with today's date
function combineDateTime(timeStr) {
    if (!timeStr) return null;

    // If it's already a full ISO datetime, just return it
    if (timeStr.includes("T") || timeStr.includes("-")) {
        return timeStr;
    }

    // Get today's date in YYYY-MM-DD
    const today = new Date().toISOString().split("T")[0];

    // Add seconds if missing
    const timeWithSeconds = timeStr.length === 5 ? `${timeStr}:00` : timeStr;

    return `${today} ${timeWithSeconds}`;
}

for (const [name, actuator] of Object.entries(actuators)) {
    if (actuator.skipped) continue;

    if (actuator.delay.active) {
        entitiesToUpdate.push({
            entity_id: `input_datetime.${name}_excecute_at`,
            value: combineDateTime(actuator.delay.execute_at)
        });
        continue;
    }

    if (actuator.timer.active) {
        // State update
        entitiesToUpdate.push({
            entity_id: `input_boolean.${name}_physical_state`,
            value: "on"
        });
        // Timer end
        entitiesToUpdate.push({
            entity_id: `input_datetime.${name}_excecute_until`,
            value: combineDateTime(actuator.timer.execute_until)
        });
    }
}

// ✅ n8n expects: return array of objects
return entitiesToUpdate.length ? entitiesToUpdate.map(e => ({ json: e })) : [{ json: {} }];

// Get all incoming items
const Items = items.map(i => i.json);

// Base Home Assistant URL
const baseUrl = "http://10.86.179.72:8123/api/states/";

// Map through items and add url_request only if entity_id exists
let updatedItems = Items
  .filter(i => i.entity_id) // skip items with null/undefined entity_id
  .map(i => ({
    ...i,
    url_request: `${baseUrl}${i.entity_id}`
  }));

// If array is empty, return empty array so HTTP Request node won't execute
if (updatedItems.length === 0) {
  return [];
}

// Wrap each item in { json: ... } as n8n expects
return updatedItems.map(i => ({ json: i }));
